-- Dedicated HRIS prototype only. PostgreSQL/RLS checks with simulated subjects;
-- this does not simulate Auth tokens or email delivery. All fixtures roll back.
begin;
do $$
declare c uuid; owner_id uuid; policy jsonb; revision bigint; steps jsonb;
 manager_id uuid:=gen_random_uuid(); hr_id uuid:=gen_random_uuid(); admin_id uuid:=gen_random_uuid();
 staff_id uuid:=gen_random_uuid(); outside_id uuid:=gen_random_uuid();
 manager_person uuid; hr_person uuid; staff_person uuid; outside_person uuid;
 manager_email text; hr_email text; admin_email text; staff_email text; outside_email text;
 request_id uuid; afternoon_id uuid; receipt_id uuid; record public.leave_requests;
begin
 if (select count(*) from public.companies)<>1 or to_regprocedure('public.submit_leave(uuid,text,date,date,text,text)') is null then raise exception 'Expected one initialized HRIS deployment with leave migration.'; end if;
 select id,companies.owner_id into strict c,owner_id from public.companies;
 manager_email:='qa-leave-manager-'||manager_id||'@example.invalid';hr_email:='qa-leave-hr-'||hr_id||'@example.invalid';admin_email:='qa-leave-admin-'||admin_id||'@example.invalid';staff_email:='qa-leave-staff-'||staff_id||'@example.invalid';outside_email:='qa-leave-outside-'||outside_id||'@example.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(manager_id,manager_email,now()),(hr_id,hr_email,now()),(admin_id,admin_email,now()),(staff_id,staff_email,now()),(outside_id,outside_email,now());
 perform set_config('request.headers','{"x-hris-leave-contract":"2"}',true);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 perform public.save_company_account(manager_id,manager_email,'manager',true,null,null);
 perform public.save_company_account(hr_id,hr_email,'hr_generalist',true,null,null);
 perform public.save_company_account(admin_id,admin_email,'administrator',true,null,null);
 perform public.save_company_account(staff_id,staff_email,'employee',true,null,null);
 perform public.save_company_account(outside_id,outside_email,'manager',true,null,null);
 select employee_id into manager_person from public.company_members where user_id=manager_id;
 select employee_id into hr_person from public.company_members where user_id=hr_id;
 select employee_id into staff_person from public.company_members where user_id=staff_id;
 select employee_id into outside_person from public.company_members where user_id=outside_id;
 update public.employees set reports_to=manager_person,joined_on='2027-01-01' where id=staff_person;
 select to_jsonb(p),p.revision into strict policy,revision from public.leave_policies p where company_id=c;
 steps:='[{"kind":"manager","employee_id":null},{"kind":"hr","employee_id":null},{"kind":"administrator","employee_id":null}]'::jsonb;
 policy:=jsonb_set(policy,'{workweek}','[1,2,3,4,5,6]');policy:=jsonb_set(policy,'{holidays}','[{"date":"2028-01-03","name":"Synthetic hosted holiday"}]');
 policy:=jsonb_set(policy,'{types,0,approval_chain}',steps);
 policy:=jsonb_set(policy,'{types}',(policy->'types')||jsonb_build_array(jsonb_build_object('code','qa_hosted_leave','name','Synthetic hosted leave','active',true,'paid',false,'use_employee_allowance',false,'annual_units',0,'accrual','unlimited','carryover_units',0,'carryover_expiry_month',3,'approval_chain',jsonb_build_array(jsonb_build_object('kind','person','employee_id',outside_person)))));
 assert public.save_leave_policy(policy,revision)=revision+1,'Policy revision did not increment';
 begin perform public.save_leave_policy(policy,revision);raise exception 'Stale policy overwrite was allowed';exception when sqlstate 'PT409' then null;end;
 perform set_config('request.jwt.claim.sub',hr_id::text,true);
 begin perform public.save_leave_policy(policy,revision+1);raise exception 'HR policy edit was allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 begin perform public.submit_leave(staff_person,'annual','2028-01-03','2028-01-03','full','Synthetic holiday');raise exception 'Holiday was charged';exception when check_violation then null;end;
 request_id:=public.submit_leave(staff_person,'annual','2028-01-04','2028-01-04','am','Synthetic morning');
 afternoon_id:=public.submit_leave(staff_person,'annual','2028-01-04','2028-01-04','pm','Synthetic afternoon');
 select * into strict record from public.leave_requests where id=request_id;
 assert record.charged_units=1 and jsonb_array_length(record.approval_steps)=3,'Half-day charge or plan not saved';
 begin perform public.submit_leave(staff_person,'annual','2028-01-04','2028-01-04','am','Synthetic duplicate');raise exception 'Duplicate morning overlap allowed';exception when exclusion_violation then null;end;
 begin perform public.review_leave(request_id,0,true,'Self approval');raise exception 'Self approval was allowed';exception when insufficient_privilege then null;end;
 begin update public.leave_requests set status='approved' where id=request_id;raise exception 'Direct status write was allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',hr_id::text,true);
 begin perform public.review_leave(request_id,0,true,'Out of order');raise exception 'Approval step was skipped';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);perform public.review_leave(request_id,0,true,'Synthetic manager approval');
 assert (select r.status='pending' and r.revision=1 from public.leave_requests r where r.id=request_id),'First stage incorrectly finalized';
 perform set_config('request.jwt.claim.sub',hr_id::text,true);
 begin perform public.review_leave(request_id,0,true,'Stale decision');raise exception 'Stale request edit was accepted';exception when sqlstate 'PT409' then null;end;
 perform public.review_leave(request_id,1,true,'Synthetic HR approval');
 perform set_config('request.jwt.claim.sub',admin_id::text,true);perform public.review_leave(request_id,2,true,'Synthetic final approval');
 assert (select r.status='approved' and r.revision=3 from public.leave_requests r where r.id=request_id),'Final stage not approved';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);perform public.cancel_leave(afternoon_id,0,'Synthetic pending cancellation');perform public.cancel_leave(request_id,3,'Synthetic future approved cancellation');
 begin perform public.cancel_leave(request_id,3,'Duplicate cancellation');raise exception 'Repeated cancellation accepted';exception when sqlstate 'PT409' then null;end;
 receipt_id:=public.submit_leave(staff_person,'qa_hosted_leave','2028-02-01','2028-02-01','full','Synthetic named reviewer');
 perform set_config('request.jwt.claim.sub',outside_id::text,true);
 assert not exists(select 1 from public.employees where id=staff_person),'Named reviewer gained full employment access';
 assert (select requester_name<>'' from public.leave_requests where id=receipt_id),'Named reviewer lacks scoped request identity';
 perform public.review_leave(receipt_id,0,true,'Synthetic named review');
 assert (select status='approved' from public.leave_requests where id=receipt_id),'Named reviewer lost their decision receipt';
 assert not exists(select 1 from public.employees where id=staff_person),'Receipt exposed full personnel record';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.save_company_account(outside_id,outside_email,'manager',false,null,null);
 perform set_config('request.jwt.claim.sub',outside_id::text,true);
 assert not exists(select 1 from public.leave_requests where id=receipt_id),'Disabled reviewer retained access';
 assert not exists(select 1 from public.leave_policies),'Disabled reviewer retained policy access';
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';
 begin perform * from public.leave_events;raise exception 'Anonymous audit read allowed';exception when insufficient_privilege then null;end;
 begin perform public.cancel_leave(request_id,4,'Anonymous');raise exception 'Anonymous cancellation allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 assert not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef),'Public definer RPC was exposed';
end;$$;
rollback;
select true as hosted_leave_policy_and_chain_checks_passed,true as all_fixtures_rolled_back;
